1	/**
2	 * Audio auto-next-chapter test.
3	 *
4	 * Verifies the chapter swap on `ended` keeps the same <audio> element and
5	 * uses LiveView push_patch (no full navigation). This is the critical
6	 * mobile-lock-screen fix: a full navigation tears down the OS audio
7	 * session, which is why autoplay used to fail when the phone was asleep.
8	 *
9	 * Requires the canonical e2e fixture: a chapter with audio that *also*
10	 * has a next chapter with audio (so `next_audio_url` is populated).
11	 * `seed_e2e_book!/1` defaults to `audio_for: [1, 2]` — chapter 1 sees
12	 * chapter 2 as the next audio-ready chapter.
13	 */
14	import { describe, it, before, after } from "node:test";
15	import assert from "node:assert";
16	import { setup, teardown, openReader, BASE_URL } from "../helpers.js";
17	
18	describe("Audio auto-next-chapter", () => {
19		let browser, page;
20	
21		before(async () => {
22			({ browser, page } = await setup());
23	
24			// Find a chapter that has audio AND a next-chapter audio URL.
25			// The fixture guarantees chapter 1 satisfies this; we still walk
26			// the bar in case the test ordering shifted.
27			await openReader(page);
28			const chapters = await page.evaluate(() => {
29				const bar = document.getElementById("chapter-bar");
30				return bar ? JSON.parse(bar.dataset.chapters) : [];
31			});
32	
33			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
34			assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
35			assert.ok(
36				chapters.length > 0,
37				"fixture must seed ≥1 chapter; check ReadaloudAudiobook.Fixtures.E2E.seed!/1",
38			);
39	
40			let found = false;
41			for (const ch of chapters) {
42				await page.goto(
43					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
44					{ waitUntil: "networkidle2" },
45				);
46				await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
47				await page.waitForSelector("#chapter-text", { timeout: 10000 });
48				// `#audio-player` is gated by audio_state == :ready; absence after
49				// chapter-text renders means this chapter has no audio. Don't fail —
50				// just walk to the next chapter.
51				const player = await page
52					.waitForSelector("#audio-player", { timeout: 1000 })
53					.catch(() => null);
54				if (player) {
55					const nextUrl = await page.$eval(
56						"#audio-player",
57						(el) => el.dataset.nextAudioUrl || "",
58					);
59					if (nextUrl) {
60						found = true;
61						break;
62					}
63				}
64			}
65			assert.ok(
66				found,
67				"fixture must seed ≥2 contiguous audio-ready chapters; the audio-* " +
68					"tests need both a current chapter and a next chapter with audio. " +
69					"Check `audio_for` in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
70			);
71		});
72	
73		after(async () => {
74			await teardown(browser);
75		});
76	
77		it("player exposes next-chapter data attrs", async () => {
78			const attrs = await page.$eval("#audio-player", (el) => ({
79				audioUrl: el.dataset.audioUrl,
80				nextAudioUrl: el.dataset.nextAudioUrl,
81				nextTimingsUrl: el.dataset.nextTimingsUrl,
82				nextChapterId: el.dataset.nextChapterId,
83				chapterId: el.dataset.chapterId,
84				bookTitle: el.dataset.bookTitle,
85				chapterTitle: el.dataset.chapterTitle,
86			}));
87			assert.ok(attrs.audioUrl, "audioUrl must be set");
88			assert.ok(attrs.nextAudioUrl, "nextAudioUrl must be set");
89			assert.ok(attrs.nextTimingsUrl, "nextTimingsUrl must be set");
90			assert.ok(attrs.nextChapterId, "nextChapterId must be set");
91			assert.notStrictEqual(
92				attrs.audioUrl,
93				attrs.nextAudioUrl,
94				"next URL must differ from current",
95			);
96			assert.ok(attrs.bookTitle, "bookTitle must be set for Media Session");
97			assert.ok(attrs.chapterTitle, "chapterTitle must be set for Media Session");
98		});
99	
100		it("Media Session metadata is registered", async (t) => {
101			// Wait for the hook to populate MediaMetadata (or for the browser
102			// to declare it doesn't support MediaSession at all).
103			await page
104				.waitForFunction(
105					() =>
106						!("mediaSession" in navigator) ||
107						navigator.mediaSession.metadata !== null,
108					{ timeout: 5000 },
109				)
110				.catch(() => {});
111			const meta = await page.evaluate(() => {
112				if (!("mediaSession" in navigator)) return null;
113				const m = navigator.mediaSession.metadata;
114				if (!m) return null;
115				return { title: m.title, artist: m.artist, album: m.album };
116			});
117			// MediaSession is a runtime browser capability, not a fixture
118			// precondition — soft-skip if the headless chromium build lacks it.
119			if (meta === null) {
120				t.skip("MediaSession not available in this browser");
121				return;
122			}
123			assert.ok(meta.title?.length > 0, "Media Session title should be set");
124			assert.ok(meta.artist?.length > 0, "Media Session artist should be set");
125		});
126	
127		it("prefetches next chapter audio into a Blob URL while current plays", async () => {
128			// Enable autoNextChapter (gates prefetch) and reload so the
129			// PersistedRecord cache picks it up.
130			await page.evaluate(() => {
131				const cur = (() => {
132					try {
133						return JSON.parse(
134							localStorage.getItem("readaloud-reader-settings") || "{}",
135						);
136					} catch {
137						return {};
