1	/**
2	 * Regression test: reader settings (fontSize, lineHeight, fontFamily, maxWidth)
3	 * survive an in-place chapter change.
4	 *
5	 * The reader applies these as inline styles on #chapter-text and
6	 * #reader-content via the ReaderStylesHook. Phoenix LiveView's morphdom
7	 * strips JS-set attributes that aren't in the server-rendered template
8	 * when it patches the DOM — so when push_patch swaps the chapter, the
9	 * inline styles get wiped. The fix re-applies settings in the hook's
10	 * `updated` lifecycle. This test pins that behavior.
11	 *
12	 * Requires the canonical e2e fixture (≥2 chapters). Run via
13	 * `mix test.e2e` — the Nix VM seeds the fixture before the suite.
14	 */
15	import { describe, it, before, after } from "node:test";
16	import assert from "node:assert";
17	import { setup, teardown, openReader } from "../helpers.js";
18	
19	describe("Reader styles persist across chapter swap", () => {
20		let browser, page;
21	
22		before(async () => {
23			({ browser, page } = await setup());
24			await openReader(page);
25			await page.waitForSelector("#chapter-text", { timeout: 5000 });
26	
27			const chapterCount = await page.evaluate(() => {
28				const bar = document.getElementById("chapter-bar");
29				return bar ? JSON.parse(bar.dataset.chapters).length : 0;
30			});
31			assert.ok(
32				chapterCount >= 2,
33				`fixture must seed ≥2 chapters to exercise push_patch; got ${chapterCount}. ` +
34					"Check ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
35			);
36		});
37	
38		after(async () => {
39			await teardown(browser);
40		});
41	
42		it("font size on #chapter-text survives next_chapter push_patch", async () => {
43			// Pick a font size that's clearly different from the default (18).
44			const TARGET_FONT_SIZE = 26;
45	
46			// Seed the persisted settings store and force the hook to apply them.
47			// We poke the store via localStorage and dispatch a storage-style
48			// trigger by re-opening the page so the hook reads the new value
49			// on mount. (Going through the slider would also work, but this is
50			// faster and doesn't depend on the slider's exact min/max range.)
51			await page.evaluate((size) => {
52				const raw = localStorage.getItem("readaloud-reader-settings");
53				const cur = raw ? JSON.parse(raw) : {};
54				cur.fontSize = size;
55				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
56			}, TARGET_FONT_SIZE);
57	
58			await openReader(page);
59			await page.waitForSelector("#chapter-text", { timeout: 5000 });
60	
61			const initialFontSize = await page.$eval(
62				"#chapter-text",
63				(el) => el.style.fontSize,
64			);
65			assert.strictEqual(
66				initialFontSize,
67				`${TARGET_FONT_SIZE}px`,
68				"sanity: hook applied seeded fontSize on initial mount",
69			);
70	
71			const startingChapterId = await page.evaluate(
72				() => window.location.pathname.match(/\/read\/(\d+)/)?.[1],
73			);
74	
75			// Click the "next chapter" button on the floating pill. This fires
76			// a phx-click="next_chapter" → push_patch on the server, which
77			// patches the DOM in place (no full page navigation).
78			await page.mouse.move(640, 400);
79			await page.mouse.move(641, 401);
80			await page.waitForSelector("#floating-pill.opacity-100", {
81				timeout: 5000,
82			});
83			await page.click('[phx-click="next_chapter"]:not([disabled])');
84	
85			// Wait for the URL to change (push_patch) AND the hook's updated()
86			// lifecycle to re-apply the inline style. Both signals are observable
87			// in the DOM directly — no need to time-box morphdom's settle.
88			await page.waitForFunction(
89				(prev, expected) => {
90					const m = window.location.pathname.match(/\/read\/(\d+)/);
91					const urlChanged = m && m[1] !== prev;
92					const styled =
93						document.getElementById("chapter-text")?.style.fontSize ===
94						`${expected}px`;
95					return urlChanged && styled;
96				},
97				{ timeout: 5000 },
98				startingChapterId,
99				TARGET_FONT_SIZE,
100			);
101	
102			const fontSizeAfterSwap = await page.$eval(
103				"#chapter-text",
104				(el) => el.style.fontSize,
105			);
106			assert.strictEqual(
107				fontSizeAfterSwap,
108				`${TARGET_FONT_SIZE}px`,
109				"fontSize must survive push_patch chapter swap — without re-apply " +
110					"in the hook's updated() lifecycle, morphdom strips the inline " +
111					"style and the article reverts to the prose-lg default size",
112			);
113		});
114	
115		it("font family and line height also survive the swap", async () => {
116			// We're already on chapter N+1 from the previous test. Set a fresh
117			// non-default fontFamily + lineHeight, reload, then swap chapters.
