1	import type { LiveViewHookSpec, ViewHookInternal } from "phoenix_live_view";
2	import type {
3	  ReadaloudHandleEvents,
4	  ReadaloudPushEvents,
5	  ReadaloudWindowEvents,
6	} from "./events";
7	
8	type EmptyPayload = undefined | Record<string, never>;
9	
10	type WindowEventDetail<K extends keyof ReadaloudWindowEvents> =
11	  ReadaloudWindowEvents[K] extends undefined
12	    ? []
13	    : [detail: ReadaloudWindowEvents[K]];
14	
15	type PushEventArgs<K extends keyof ReadaloudPushEvents> =
16	  ReadaloudPushEvents[K] extends EmptyPayload
17	    ? []
18	    : [payload: ReadaloudPushEvents[K]];
19	
20	export interface HookContext<
21	  TEl extends HTMLElement = HTMLElement,
22	  TDataset = Record<string, string | undefined>,
23	> {
24	  readonly el: TEl;
25	  readonly dataset: Readonly<TDataset>;
26	
27	  on<K extends keyof HTMLElementEventMap>(
28	    target: HTMLElement | Document,
29	    event: K,
30	    handler: (e: HTMLElementEventMap[K]) => void,
31	    opts?: AddEventListenerOptions,
32	  ): void;
33	  on<K extends keyof WindowEventMap>(
34	    target: Window,
35	    event: K,
36	    handler: (e: WindowEventMap[K]) => void,
37	    opts?: AddEventListenerOptions,
38	  ): void;
39	  on<K extends keyof ReadaloudWindowEvents>(
40	    target: Window,
41	    event: K,
42	    handler: ReadaloudWindowEvents[K] extends undefined
43	      ? () => void
44	      : (detail: ReadaloudWindowEvents[K]) => void,
45	  ): void;
46	
47	  dispatch<K extends keyof ReadaloudWindowEvents>(
48	    event: K,
49	    ...detail: WindowEventDetail<K>
50	  ): void;
51	
52	  pushEvent<K extends keyof ReadaloudPushEvents>(
53	    event: K,
54	    ...payload: PushEventArgs<K>
55	  ): void;
56	
57	  handleEvent<K extends keyof ReadaloudHandleEvents>(
58	    event: K,
59	    handler: (payload: ReadaloudHandleEvents[K]) => void,
60	  ): void;
61	
62	  onDestroy(fn: () => void): void;
63	  onUpdate(fn: () => void): void;
64	}
65	
66	const READALOUD_EVENT_PREFIX_RE =
67	  /^(audio:|manual-scroll$|auto-scroll-|word-action$|toggle-pill$|chapter-bar-close$|readaloud:|phx:)/;
68	
69	function isReadaloudEvent(event: string): boolean {
70	  return READALOUD_EVENT_PREFIX_RE.test(event);
71	}
72	
73	export function defineHook<
74	  TEl extends HTMLElement = HTMLElement,
75	  TDataset = Record<string, string | undefined>,
76	>(setup: (ctx: HookContext<TEl, TDataset>) => void): LiveViewHookSpec {
77	  return {
78	    mounted(this: ViewHookInternal): void {
79	      const disposers: Array<() => void> = [];
80	      const updateHandlers: Array<() => void> = [];
81	      const lv = this;
82	
83	      const ctx: HookContext<TEl, TDataset> = {
84	        el: this.el as TEl,
85	        dataset: this.el.dataset as unknown as Readonly<TDataset>,
86	
87	        on(
88	          target: EventTarget,
89	          event: string,
90	          handler: (arg: unknown) => void,
91	          opts?: AddEventListenerOptions,
92	        ): void {
93	          if (target === window && isReadaloudEvent(event)) {
94	            const wrapped = (e: Event): void => {
95	              const detail = (e as CustomEvent).detail;
96	              handler(detail);
97	            };
98	            window.addEventListener(event, wrapped);
99	            disposers.push(() => window.removeEventListener(event, wrapped));
100	          } else {
101	            target.addEventListener(event, handler as EventListener, opts);
102	            disposers.push(() =>
103	              target.removeEventListener(event, handler as EventListener, opts),
104	            );
105	          }
106	        },
107	
108	        dispatch(event: string, detail?: unknown): void {
109	          window.dispatchEvent(new CustomEvent(event, { detail }));
110	        },
111	
112	        pushEvent(event: string, payload?: object): void {
113	          lv.pushEvent(event, payload ?? {});
114	        },
115	
116	        handleEvent(event: string, handler: (payload: never) => void): void {
117	          const ref = lv.handleEvent(event, handler as (p: unknown) => void);
118	          disposers.push(() => lv.removeHandleEvent(ref));
119	        },
120	
121	        onDestroy(fn: () => void): void {
122	          disposers.push(fn);
123	        },
124	
125	        onUpdate(fn: () => void): void {
126	          updateHandlers.push(fn);
127	        },
128	      };
129	
130	      (this as unknown as { _ctxDisposers: Array<() => void> })._ctxDisposers =
131	        disposers;
132	      (
133	        this as unknown as { _ctxUpdateHandlers: Array<() => void> }
134	      )._ctxUpdateHandlers = updateHandlers;
135	
136	      try {
137	        setup(ctx);
138	      } catch (err) {
139	        for (const dispose of disposers) {
140	          try {
141	            dispose();
142	          } catch {}
143	        }
144	        throw err;
145	      }
146	    },
147	
148	    updated(this: ViewHookInternal): void {
149	      const handlers = (
150	        this as unknown as { _ctxUpdateHandlers?: Array<() => void> }
151	      )._ctxUpdateHandlers;
152	      if (!handlers) return;
153	      for (const fn of handlers) {
154	        try {
155	          fn();
156	        } catch (err) {
157	          console.error("hook update handler threw:", err);
158	        }
159	      }
160	    },
161	
162	    destroyed(this: ViewHookInternal): void {
163	      const disposers = (
164	        this as unknown as { _ctxDisposers?: Array<() => void> }
165	      )._ctxDisposers;
166	      if (!disposers) return;
167	      for (const dispose of disposers) {
168	        try {
169	          dispose();
170	        } catch (err) {
171	          console.error("hook disposer threw:", err);
172	        }
173	      }
174	    },
175	  };
176	}
